<?php
require_once __DIR__.'/../includes/auth.php';require_role(['super_admin','manager','receptionist','trainer']);$bid=current_branch_id();$myTrainerId=user()['role']==='trainer'?(int)(query_value('SELECT id FROM trainers WHERE user_id=?',[user()['id']])?:0):0;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='add'&&in_array(user()['role'],['super_admin','manager'])){db()->prepare("INSERT INTO classes(branch_id,trainer_id,title,category,recurring_day,start_time,end_time,capacity,room,status) VALUES(?,?,?,?,?,?,?,?,?,'active')")->execute([$bid,$_POST['trainer_id']?:null,trim($_POST['title']),trim($_POST['category']),$_POST['recurring_day'],$_POST['start_time'],$_POST['end_time'],(int)$_POST['capacity'],trim($_POST['room'])]);$cid=(int)db()->lastInsertId();audit_log('class.created','class',$cid,trim($_POST['title']).' created');flash('success','Class added to schedule.');redirect('app/classes.php');}if($action==='book'){if(user()['role']==='trainer' && !(int)query_value('SELECT COUNT(*) FROM members WHERE id=? AND branch_id=? AND trainer_id=?',[(int)$_POST['member_id'],$bid,$myTrainerId])){http_response_code(403);exit('403 — You may book only assigned members.');}db()->prepare("INSERT IGNORE INTO class_bookings(class_id,member_id,status) VALUES(?,?,'booked')")->execute([(int)$_POST['class_id'],(int)$_POST['member_id']]);audit_log('class.booking','class',(int)$_POST['class_id'],'Member #'.(int)$_POST['member_id'].' booked');flash('success','Class booking created.');redirect('app/classes.php');}}
$rows=query_all("SELECT c.*,t.name trainer_name,(SELECT COUNT(*) FROM class_bookings b WHERE b.class_id=c.id AND b.status IN('booked','attended')) booked FROM classes c LEFT JOIN trainers t ON t.id=c.trainer_id WHERE c.branch_id=? ORDER BY FIELD(c.recurring_day,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'),c.start_time",[$bid]);$trainers=query_all("SELECT id,name FROM trainers WHERE branch_id=? AND status='active' ORDER BY name",[$bid]);if(user()['role']==='trainer'){$members=query_all("SELECT id,member_code,CONCAT(first_name,' ',last_name) name FROM members WHERE branch_id=? AND trainer_id=? AND status='active' AND membership_end>=CURDATE() ORDER BY first_name",[$bid,$myTrainerId]);}else{$members=query_all("SELECT id,member_code,CONCAT(first_name,' ',last_name) name FROM members WHERE branch_id=? AND status='active' AND membership_end>=CURDATE() ORDER BY first_name",[$bid]);}
$pageTitle='Classes & Booking';include __DIR__.'/../includes/header.php'; ?>
<div class="page-actions"><?php if(in_array(user()['role'],['super_admin','manager'])): ?><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#classModal"><i class="fa-solid fa-plus me-2"></i>Create class</button><?php endif; ?></div><div class="grid-3"><?php foreach($rows as $c): $pct=min(100,round(((int)$c['booked']/max(1,(int)$c['capacity']))*100)); ?><div class="panel"><div class="d-flex justify-content-between"><span class="badge-soft badge-info"><?= e($c['category']) ?></span><span class="text-muted small"><?= e($c['recurring_day']) ?></span></div><h3 style="font-family:Manrope;font-size:1.1rem" class="mt-3 mb-1"><?= e($c['title']) ?></h3><p class="text-muted small"><i class="fa-regular fa-clock me-1"></i><?= date('g:i A',strtotime($c['start_time'])) ?>–<?= date('g:i A',strtotime($c['end_time'])) ?> · <?= e($c['room']) ?></p><div class="mini-row mt-3"><div class="mini-avatar"><i class="fa-solid fa-person-chalkboard"></i></div><div class="grow"><strong><?= e($c['trainer_name']??'TBA') ?></strong><small>Coach</small></div></div><div class="d-flex justify-content-between small mt-3"><span class="text-muted">Booked</span><span><?= (int)$c['booked'] ?>/<?= (int)$c['capacity'] ?></span></div><div class="progress-thin mt-2"><span style="width:<?= $pct ?>%"></span></div><button class="btn btn-dark btn-sm w-100 mt-3" data-bs-toggle="modal" data-bs-target="#bookModal" data-class="<?= $c['id'] ?>" data-name="<?= e($c['title']) ?>">Book member</button></div><?php endforeach; ?></div>
<div class="modal fade" id="classModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="add"><div class="modal-header"><h5>Create class</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-12"><label class="form-label">Class title</label><input name="title" class="form-control" required></div><div class="col-6"><label class="form-label">Category</label><input name="category" class="form-control" placeholder="Yoga, HIIT..."></div><div class="col-6"><label class="form-label">Trainer</label><select name="trainer_id" class="form-select"><option value="">TBA</option><?php foreach($trainers as $t): ?><option value="<?= $t['id'] ?>"><?= e($t['name']) ?></option><?php endforeach; ?></select></div><div class="col-6"><label class="form-label">Day</label><select name="recurring_day" class="form-select"><?php foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] as $d): ?><option><?= $d ?></option><?php endforeach; ?></select></div><div class="col-3"><label class="form-label">Start</label><input type="time" name="start_time" class="form-control" required></div><div class="col-3"><label class="form-label">End</label><input type="time" name="end_time" class="form-control" required></div><div class="col-6"><label class="form-label">Capacity</label><input type="number" name="capacity" value="20" class="form-control"></div><div class="col-6"><label class="form-label">Room / zone</label><input name="room" class="form-control"></div></div></div><div class="modal-footer"><button class="btn btn-primary">Create class</button></div></form></div></div></div>
<div class="modal fade" id="bookModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="book"><input type="hidden" name="class_id" id="bookClassId"><div class="modal-header"><h5>Book member · <span id="bookClassName"></span></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Active member</label><select name="member_id" class="form-select"><?php foreach($members as $m): ?><option value="<?= $m['id'] ?>"><?= e($m['member_code'].' — '.$m['name']) ?></option><?php endforeach; ?></select></div><div class="modal-footer"><button class="btn btn-primary">Confirm booking</button></div></form></div></div></div>
<?php $pageScript='<script>document.getElementById("bookModal").addEventListener("show.bs.modal",e=>{const b=e.relatedTarget;document.getElementById("bookClassId").value=b.dataset.class;document.getElementById("bookClassName").textContent=b.dataset.name;});</script>';include __DIR__.'/../includes/footer.php'; ?>